// @minecraft/server sahte modulu - sadece test icin
export const _durum = {
  ozellikler: new Map(),
  entityHurtCb: [],
  entityHitCb: [],
  mermiCb: [],
  blokKirCb: [],
  tick: 0,
  araliklar: [],   // {id, cb, n, sonrakiTick, iptal}
  zamanlar: [],    // {id, cb, tick, iptal}
  sonrakiId: 1,
  itemUseCb: [],
  playerLeaveCb: [],
  playerSpawnCb: [],
  scriptEventCb: [],
  itemCompleteUseCb: [],
  chatSendCb: [],
  sohbet: [],
  oyuncular: [],
  // Oyunun esya kayit defteri. Testler bunu doldurup bosaltarak
  // "esya kayitli degil" durumunu taklit ediyor.
  kayitliEsyalar: new Set(),
  kayitliVarliklar: new Set(),
  varliklar: [],
  boyut: undefined
};

/* MolangVariableMap -- gercek API'deki sinifin sahtesi (v7.18).
   Gercegi parcaciga variable.<ad>.x/.y/.z gibi degerler
   gecirir; burada yalnizca NE GECIRILDIGI kaydediliyor, cunku
   sinanan sey "dogru hiz gecti mi", parcacigin cizimi degil.  */
export class MolangVariableMap {
  constructor() { this._deger = {}; }
  setFloat(ad, sayi) { this._deger[ad] = sayi; }
  setVector3(ad, v) { this._deger[ad] = { x: v.x, y: v.y, z: v.z }; }
  setColorRGB(ad, c) { this._deger[ad] = c; }
  setColorRGBA(ad, c) { this._deger[ad] = c; }
  setSpeedAndDirection(ad, hiz, yon) { this._deger[ad] = { hiz, yon }; }
}

export class ItemStack {
  constructor(tip, adet = 1) {
    if (!_durum.kayitliEsyalar.has(tip)) {
      throw new Error("Unknown item type: " + tip);
    }
    this.typeId = tip;
    this.amount = adet;
  }
}

export const ItemTypes = {
  get(tip) {
    return _durum.kayitliEsyalar.has(tip) ? { id: tip } : undefined;
  }
};

export const system = {
  get currentTick() { return _durum.tick; },
  runInterval(cb, n = 1) {
    const id = _durum.sonrakiId++;
    _durum.araliklar.push({ id, cb, n, sonrakiTick: _durum.tick + n, iptal: false });
    return id;
  },
  runTimeout(cb, n = 1) {
    const id = _durum.sonrakiId++;
    _durum.zamanlar.push({ id, cb, tick: _durum.tick + n, iptal: false });
    return id;
  },
  clearRun(id) {
    for (const a of _durum.araliklar) if (a.id === id) a.iptal = true;
    for (const z of _durum.zamanlar) if (z.id === id) z.iptal = true;
  },
  afterEvents: {
    scriptEventReceive: { subscribe(cb) { _durum.scriptEventCb.push(cb); } }
  }
};

export const world = {
  afterEvents: {
    itemUse: { subscribe(cb) { _durum.itemUseCb.push(cb); } },
    playerLeave: { subscribe(cb) { _durum.playerLeaveCb.push(cb); } },
    playerSpawn: { subscribe(cb) { _durum.playerSpawnCb.push(cb); } },
    itemCompleteUse: { subscribe(cb) { _durum.itemCompleteUseCb.push(cb); } },
    entityHurt: { subscribe(cb) { _durum.entityHurtCb.push(cb); } },
    /* Bot bir seye VURDU (v4.34, Ilkel Besli).
       _durum.vurusOlayiYok = true -> olay hic yokmus gibi. */
    get entityHitEntity() {
      if (_durum.vurusOlayiYok) return undefined;
      return { subscribe(cb) { _durum.entityHitCb.push(cb); } };
    },
    /* Oyuncu bir blok kirdi (v4.50, mezar acma).
       _durum.blokKirOlayiYok = true -> olay hic yokmus gibi. */
    get playerBreakBlock() {
      if (_durum.blokKirOlayiYok) return undefined;
      return { subscribe(cb) { _durum.blokKirCb.push(cb); } };
    },
    /* Botun mermisi bir seye degdi (v4.47, Miskel'in oku).
       _durum.mermiOlayiYok = true -> olay hic yokmus gibi. */
    get projectileHitEntity() {
      if (_durum.mermiOlayiYok) return undefined;
      return { subscribe(cb) { _durum.mermiCb.push(cb); } };
    }
  },
  /* beforeEvents.chatSend: gercek API'de mesaj GONDERILMEDEN once
     cagriliyor ve olay.cancel = true ile iptal edilebiliyor.
     _durum.chatSendYok = true yapilirsa olay hic yokmus gibi
     davraniyor -- "surumde yoksa paket olmuyor mu" testi icin.   */
  get beforeEvents() {
    if (_durum.chatSendYok) return {};
    return {
      chatSend: { subscribe(cb) { _durum.chatSendCb.push(cb); } }
    };
  },
  sendMessage(m) { _durum.sohbet.push(m); },

  /* Bot varligini kimlikten bulmak icin. Gercek API'de de var;
     yoksa _durum.getEntityYok = true ile kapatilabiliyor.      */
  getEntity(id) {
    if (_durum.getEntityYok) return undefined;
    for (const v of _durum.varliklar) if (v.id === id) return v;
    return undefined;
  },
  getDimension(id) { return _durum.boyut; },
  getAllPlayers() { return _durum.oyuncular; },

  /* Kalici dunya ozellikleri. Gercek API'de dunya kaydediliyor;
     burada _durum.ozellikler'de duruyor. Testler dunyayi yeniden
     yuklemeyi ozellikSifirla() ile taklit ediyor.               */
  setDynamicProperty(ad, deger) {
    if (deger === undefined) _durum.ozellikler.delete(ad);
    else _durum.ozellikler.set(ad, deger);
  },
  getDynamicProperty(ad) { return _durum.ozellikler.get(ad); }
};

export function tickIlerlet(adet = 1) {
  for (let i = 0; i < adet; i++) {
    _durum.tick++;
    for (const z of _durum.zamanlar) {
      if (!z.iptal && z.tick === _durum.tick) { z.iptal = true; z.cb(); }
    }
    for (const a of _durum.araliklar) {
      if (a.iptal) continue;
      if (_durum.tick >= a.sonrakiTick) { a.sonrakiTick = _durum.tick + a.n; a.cb(); }
    }
  }
}

export function itemUseTetikle(olay) { for (const cb of _durum.itemUseCb) cb(olay); }

export function vurusTetikle(olay) { for (const cb of _durum.entityHitCb) cb(olay); }
export function hasarTetikle(olay) { for (const cb of _durum.entityHurtCb) cb(olay); }

/* Bir mermi bir varliga degdi. Gercek olayda hedef
   getEntityHit() ile geliyor -- burada da oyle.              */
export function mermiTetikle({ source, kurban }) {
  const olay = {
    source,
    projectile: { typeId: "minecraft:arrow" },
    getEntityHit: () => (kurban ? { entity: kurban } : undefined)
  };
  for (const cb of _durum.mermiCb) cb(olay);
}

/* Oyuncu bir blok kirdi. Gercek olayda blok NESNESI geliyor. */
export function blokKirTetikle(oyuncu, konum) {
  const olay = {
    player: oyuncu,
    block: { location: { x: konum.x, y: konum.y, z: konum.z } }
  };
  for (const cb of _durum.blokKirCb) cb(olay);
}

export function itemCompleteUseTetikle(olay) {
  for (const cb of _durum.itemCompleteUseCb) cb(olay);
}

/* Sohbete bir mesaj yazilmis gibi yapar. Donen deger: mesaj
   iptal edildi mi (yani komut olarak yutuldu mu).              */
export function sohbetTetikle(oyuncu, mesaj) {
  const olay = { sender: oyuncu, message: mesaj, cancel: false };
  for (const cb of _durum.chatSendCb) cb(olay);
  return olay.cancel === true;
}

export function scriptEventTetikle(olay) {
  for (const cb of _durum.scriptEventCb) cb(olay);
}

/* Varlik tipi kayit defteri: botDenetimi() bunu okuyor. */
export const EntityTypes = {
  get(id) { return _durum.kayitliVarliklar.has(id) ? { id } : undefined; }
};

export function varlikKaydet(...tipler) {
  for (const t of tipler) _durum.kayitliVarliklar.add(t);
}

export function esyaKaydet(...tipler) {
  for (const t of tipler) _durum.kayitliEsyalar.add(t);
}

export function esyaSil(...tipler) {
  for (const t of tipler) _durum.kayitliEsyalar.delete(t);
}
